import {WEEKDAYS,defaultProfile,validateProfile,buildStudyPlan,coursePace,localParts} from './domain.mjs';
import {previewState,exampleDraft} from './preview.mjs';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shapes={agent:'<path d="M7 4h10a3 3 0 0 1 3 3v7a3 3 0 0 1-3 3h-6l-5 4v-4H5a2 2 0 0 1-2-2V8a4 4 0 0 1 4-4Z"/><path d="M8 10h8m-8 3h5"/>',work:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M9 5V3h6v2M8 10h8M8 14h8M8 18h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',connect:'<path d="m9 15 6-6m-8 3-2 2a4 4 0 0 0 6 6l3-3m-4-10 3-3a4 4 0 1 1 6 6l-2 2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',up:'<path d="M12 19V5m-6 6 6-6 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',check:'<path d="m5 12 4 4L19 6"/>',book:'<path d="M12 5v16M3 3h5a4 4 0 0 1 4 2 4 4 0 0 1 4-2h5v16h-5a4 4 0 0 0-4 2 4 4 0 0 0-4-2H3z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v6h5M8 14h8M8 17h6"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',shield:'<path d="m12 3 8 3v5c0 5-4 8-8 10-4-2-8-5-8-10V6z"/><path d="m8 12 3 3 5-6"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1"/>',moon:'<path d="M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11Z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3v.1"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.file}</svg>`;
const S={view:'agent',demo:true,data:previewState(),config:{},composer:'',allowDelegation:false,tab:'assignments',profileTab:'routine',editProfile:null,models:[],accounts:[],detail:null,dirty:false,file:0,busy:false,lastPoll:0};
const root=document.querySelector('#app'),modal=document.querySelector('#modal');
const course=id=>S.data.snapshot.courses.find(c=>c.id===Number(id))||{code:'Course',name:'Course'};
const dLabel=date=>date?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:S.data.profile.timezone}).format(new Date(date)):'No due date';
const time=date=>new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit',timeZone:S.data.profile.timezone}).format(new Date(date));
const due=date=>date?`Due ${dLabel(date)}`:'No due date';
const safeLink=value=>{try{const u=new URL(value);return u.protocol==='https:'?h(u.href):'#';}catch{return '#';}};
const jobActive=j=>['queued','running'].includes(j.status);
const stageLabel=d=>({created:'Queued',planned:'Drafting',written:'Needs review',ready:S.demo?'Example draft':'Ready for review',submitted:'Submitted',submitting:'Submitting',needs_manual_check:'Check Canvas'})[d.stage]||d.stage;
function toast(text,error=false){const t=document.querySelector('#toast');t.textContent=text;t.className='visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',error?9000:5500);}
async function api(op,data){const r=await fetch('/api/workspace?'+new URLSearchParams({op}),{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json'},...(data===undefined?{}:{body:JSON.stringify(data)})});const v=await r.json().catch(()=>({error:'The server returned an unreadable response.'}));if(!r.ok){const e=new Error(v.error||'Request failed.');e.status=r.status;throw e;}return v;}
async function reload({renderPage=true}={}){if(S.demo)return;if(S.busy)return;try{const data=await api('state');const changed=data.version!==S.data.version;S.data=data;if(renderPage&&changed&&!modal.open&&!['profile'].includes(S.view))render();}catch(e){if(e.status===401){S.demo=true;S.data=previewState();render();toast('Your session ended. Sign in again.',true);}else throw e;}}
function navigate(view){S.view=view;S.editProfile=null;document.body.classList.remove('mobile-nav');history.replaceState(null,'','#'+view);render();}
function show(html,wide=false){modal.className=wide?'wide':'';modal.innerHTML=html;if(!modal.open)modal.showModal();}
const modalHead=(title,sub='')=>`<div class="dialog-header"><div><h2 id="dialog-title">${h(title)}</h2><p>${h(sub)}</p></div><button class="icon-button" data-act="close" aria-label="Close">${icon('close')}</button></div>`;
const header=(title,description,action='')=>`<div class="view-header"><div><h1>${h(title)}</h1><p>${h(description)}</p></div>${action}</div>`;
const blank=(title,description,action='')=>`<div class="blank">${icon('work')}<h3>${h(title)}</h3><p>${h(description)}</p>${action}</div>`;
function taskRows(assignments,mini=false){return assignments.map((a,i)=>`<div class="${mini?'compact-row':'work-row'}">${mini?`<i class="course-dot c${i%3}"></i>`:icon(a.submission_types.includes('online_upload')?'code':'file')}<div class="row-title"><strong>${h(a.name)}</strong><small>${h(course(a.course_id).code)} &nbsp;·&nbsp; ${h(due(a.due_at))}</small></div><div class="row-actions">${a.submitted?'<span class="status done">Submitted</span>':`<button class="${mini?'text-button':'btn small'}" data-delegate="${a.id}" data-course="${a.course_id}">${S.demo?'Try delegation':'Delegate'} ${icon('arrow')}</button>`}${!mini&&a.url?`<a class="mini-link" href="${safeLink(a.url)}" target="_blank" rel="noreferrer">Canvas</a>`:''}</div></div>`).join('');}
function contextPanel(){const p=S.data.profile,work=p.commitments.find(c=>c.kind==='work'),inProgress=S.data.jobs.filter(jobActive),ready=S.data.drafts.filter(d=>d.stage==='ready');return `<aside class="context-panel"><h2 class="context-title">In the background ${icon('work')}</h2><section class="context-section"><div class="context-eyebrow">YOUR AGENT</div>${inProgress.length?inProgress.slice(0,3).map(j=>`<div class="context-event">${icon('file')}<div><strong>${h(j.title)}</strong><p>${h(j.status==='running'?'Working on it':j.step==='review'?'Queued for review':'Queued')}</p></div></div>`).join(''):ready.length?`<div class="context-event">${icon('check')}<div><strong>${ready.length} ${S.demo?'example':'completed'} draft${ready.length>1?'s':''}</strong><p>Ready for you to look over.</p></div></div>`:`<p class="context-message">Nothing delegated yet.<br>Hand off an assignment whenever you need a little room.</p>`}<button class="text-button" data-nav="work">View my work ${icon('arrow')}</button></section><section class="context-section"><div class="context-eyebrow">${S.demo?'EXAMPLE ROUTINE':'YOUR ROUTINE'}</div>${work?`<div class="context-event">${icon('clock')}<div><strong>${h(work.title)}</strong><p>${work.days.map(d=>WEEKDAYS[d]).join(', ')}<br>${h(work.start)}–${h(work.end)}${work.end<work.start?' · next day':''}</p></div></div>`:`<p class="context-message">Tell me about your work, classes and the time you want to keep for yourself.</p>`}<div class="context-event">${icon('calendar')}<div><strong>${p.max_daily_minutes/60} hours of study, at most</strong><p>${p.session_minutes}-minute sessions, with breaks.<br>${p.confirmed?'Set by you.':'Starting defaults — confirm in About you.'}</p></div></div><button class="text-button" data-nav="schedule">See my week ${icon('arrow')}</button></section><section class="context-section"><div class="context-eyebrow">WHAT WORKS FOR YOU</div><div class="memory-chip">${icon('book')}<span>${h(({ 'worked-examples':'A worked example, then the explanation.','practice-first':'Try it yourself, then get feedback.','short-explanations':'Keep explanations short and concrete.','visual-explanations':'Use diagrams when they help.','mixed':'Adapt the explanation to the topic.'})[p.preferences.format])}</span></div><p class="context-message">${p.observations.length?`${p.observations.length} study check-ins. Pace is estimated separately for each class.`:'Learning your pace starts with your first study check-in.'}</p><button class="text-button" data-nav="profile">Edit what I know ${icon('arrow')}</button></section><p class="context-footer">${S.demo?'Sample data. Your real workspace starts empty.':'Your context belongs to you. Review or remove it any time.'}</p></aside>`;}
function composer(){return `<div class="composer-wrap"><form id="chat-form" class="composer"><label class="sr-only" for="prompt">Message your agent</label><textarea id="prompt" name="prompt" rows="2" maxlength="8000" placeholder="I’m working late. Can you take care of the scheduling lab?">${h(S.composer)}</textarea><div class="composer-bottom"><div class="composer-tools"><button type="button" class="icon-button" data-nav="work" aria-label="Choose an assignment">${icon('plus')}</button><button type="button" class="model-label" data-nav="connections">${icon('agent')} ${S.demo?'Preview agent':S.data.ai?.model?h(S.data.ai.model):'Connect ChatGPT'} ${icon('down')}</button></div><button type="submit" class="send" aria-label="Send message" ${S.busy?'disabled':''}>${icon('up')}</button></div></form><div class="composer-foot"><label class="inline-check"><input type="checkbox" id="delegate-toggle" ${S.allowDelegation?'checked':''}>Allow assignment drafting</label><span>${S.demo?'Preview only · no real model calls':'Uses your ChatGPT plan · never auto-submits'}</span></div></div>`;}
function agentView(){const d=S.data,has=d.messages.length>0;return `<div class="agent-layout"><div class="agent-center"><div class="agent-topline"><span class="quiet-label"><i class="dot"></i>${S.demo?'A preview of your workspace':'Your student agent'}</span><span>${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></div>${has?`<div class="messages">${d.messages.map(m=>`<article class="message ${h(m.role)}">${m.role==='assistant'?`<div class="message-label">${icon('agent')}Canvasly${S.demo?' · example response':''}</div>`:''}<div class="message-text">${h(m.text)}</div>${m.draft_id?`<div class="message-actions"><button class="btn small" data-draft="${h(m.draft_id)}">Open work ${icon('arrow')}</button></div>`:''}</article>`).join('')}${d.jobs.filter(j=>j.kind==='chat'&&['queued','running','paused'].includes(j.status)).map(j=>`<div class="task-progress">${h(j.status==='paused'?j.error||'Paused':j.status==='queued'?'Your message is queued.':'Your agent is working.')}<button data-job="${h(j.id)}" data-control="${j.status==='paused'?'resume':'pause'}">${j.status==='paused'?'Resume':'Pause'}</button></div>`).join('')}</div>`:`<section class="intro"><div class="agent-symbol">${icon('agent')}</div><h1>What can I take<br>off your plate?</h1><p>Hand off the work you can’t get to.<br>Make time for the things you want to understand.</p></section>`}${composer()}${!has?`<div class="suggestions"><button class="suggestion" data-nav="work">${icon('file')}Delegate an assignment</button><button class="suggestion" data-suggest="Help me understand linear regression with a worked example.">${icon('book')}Work through a concept</button><button class="suggestion" data-act="plan">${icon('calendar')}Plan around my week</button></div><section class="pickup"><div class="section-label"><h2>${S.demo?'FROM AN EXAMPLE SEMESTER':'FROM YOUR COURSES'}</h2><button class="text-button" data-nav="work">View all</button></div>${d.snapshot.assignments.length?taskRows(d.snapshot.assignments.filter(a=>!a.submitted).slice(0,3),true):`<div class="compact-row"><div class="row-title"><strong>Your coursework goes here</strong><small>Connect Canvas to give your agent the full picture.</small></div><button class="text-button" data-nav="connections">Connect ${icon('arrow')}</button></div>`}</section>`:''}<div class="home-foot"><span>${icon('shield')} Your work stays in your control.</span><span>Agent first. Everything else, around you.</span></div></div>${contextPanel()}</div>`;}
function workView(){const d=S.data,active=d.jobs.filter(j=>j.kind==='draft'),drafts=d.drafts;return `<section class="view">${header('My work','Choose what to do yourself and what to hand off. Finished drafts land here for your review.',`<button class="btn" data-act="sync">${icon('refresh')}Sync Canvas</button>`)}<div class="tabs"><button class="${S.tab==='assignments'?'active':''}" data-work-tab="assignments">Assignments <span class="muted">${d.snapshot.assignments.length}</span></button><button class="${S.tab==='delegated'?'active':''}" data-work-tab="delegated">Delegated <span class="muted">${drafts.length}</span></button></div>${S.demo?'<p class="muted">Example courses and assignments. Connect your accounts for real work.</p>':''}${S.tab==='assignments'?(d.snapshot.assignments.length?`<div class="work-list">${taskRows(d.snapshot.assignments)}</div>`:blank('Give your agent some context.','Connect your school so Canvasly can read the actual instructions, materials and deadlines.',`<button class="btn primary" data-nav="connections">Connect Canvas</button>`)):(drafts.length?`<div class="work-list">${drafts.map(draft=>{const j=active.find(j=>j.draft_id===draft.id&&j.status!=='done');return `<div class="work-row">${icon(draft.format==='online_upload'?'code':'file')}<div class="row-title"><strong>${h(draft.title)}</strong><small>${h(course(draft.course_id).code)}${draft.created_at?' · '+dLabel(draft.created_at):''}</small>${j?.error?`<p class="row-error">${h(j.error)}</p>`:''}</div><div class="row-actions"><span class="status ${h(j?.status||draft.stage)}">${h(j?.status==='paused'?'Paused':j?.status==='running'?j.step==='review'?'Reviewing':'Working':stageLabel(draft))}</span>${j&&['queued','running','paused'].includes(j.status)?`<button class="text-button" data-job="${h(j.id)}" data-control="${j.status==='paused'?'resume':'pause'}">${j.status==='paused'?'Resume':'Pause'}</button>`:''}<button class="btn small" data-draft="${h(draft.id)}">${draft.deliverable?'Open work':'View task'}</button></div></div>`;}).join('')}</div>`:blank('A little room in your day.','Delegate an assignment from your course list. Your agent reads the brief, creates the deliverable and checks the requirements.',`<button class="btn" data-work-tab="assignments">Choose an assignment</button>`))}${S.data.snapshot.warnings?.length?`<div class="callout warning">${S.data.snapshot.warnings.map(h).join('<br>')}</div>`:''}<p class="muted top-space">${S.demo?'No background work runs in preview mode.':S.config.local?'Queued work continues while this local server and computer are running—even after you close the browser.':'Hosted work requires a running worker or configured scheduler. Closing the browser does not itself start a worker.'}</p></section>`;}
function scheduleView(){const plan=S.data.plan,p=S.data.profile,dates=[];for(let n=0;n<7;n++){const t=Date.now()+n*86400000,parts=localParts(t,p.timezone);dates.push({...parts,day:new Date(t).toLocaleDateString('en-US',{weekday:'short',timeZone:p.timezone}),number:Number(parts.date.slice(-2))});}return `<section class="view">${header('A week that fits your life.','Your obligations come first. Study time fits around them—not the other way around.',`<button class="btn primary" data-act="plan">${icon('refresh')}${plan?'Rebuild my plan':'Make my plan'}</button>`)}${!p.confirmed?`<div class="callout warning">Start by confirming your work schedule and real availability. <button class="mini-link" data-nav="profile">Set my routine</button></div>`:''}<div class="week-summary"><div><strong>${plan?Number((plan.total_minutes/60).toFixed(1)):'—'} <span class="muted">hours</span></strong><small>Planned study</small></div><div><strong>${p.commitments.length}</strong><small>Protected commitments</small></div><div><strong>${p.session_minutes} <span class="muted">min</span></strong><small>Your session length</small></div></div><div class="week-grid">${dates.map(day=>{const blocks=p.commitments.filter(c=>c.days.includes(day.weekday)),sessions=(plan?.sessions||[]).filter(s=>localParts(s.start,p.timezone).date===day.date);return `<div class="day-column"><div class="day-title">${day.day}<strong>${day.number}</strong></div>${blocks.map(c=>`<div class="slot busy">${h(c.start)}–${h(c.end)}${c.end<c.start?' +1':''}<b>${h(c.title)}</b></div>`).join('')}${sessions.map(s=>`<div class="slot">${h(time(s.start))} · ${s.minutes} min<b>${h(s.title)}</b></div>`).join('')}${!blocks.length&&!sessions.length?'<p class="day-empty">Room to breathe</p>':''}</div>`;}).join('')}</div>${plan?.unscheduled.length?`<div class="callout warning"><strong>Not everything fits.</strong><br>${plan.unscheduled.map(u=>`${h(u.title)}: ${u.remaining_minutes} minutes still need a place. ${h(u.reason)}`).join('<br>')}</div>`:''}<div class="form-actions"><button class="btn" data-nav="profile">${icon('profile')}Edit my availability</button><button class="btn" data-act="checkin">${icon('check')}Log a study session</button></div><p class="muted">${S.demo?'Illustrative routine, not your actual schedule. ':''}${h(p.timezone)} · Overnight commitments include the next morning. Calendar connections are not yet implemented; enter your commitments in About you.</p></section>`;}
const field=(label,name,value,type='text',other='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${h(value)}" ${other}></label>`;
function profileView(){S.editProfile ||= structuredClone(S.data.profile);const p=S.editProfile;return `<section class="view">${header('About you','Not another productivity profile. Just the context your agent needs to make sensible decisions.')}<div class="tabs"><button class="${S.profileTab==='routine'?'active':''}" data-profile-tab="routine">My routine</button><button class="${S.profileTab==='learning'?'active':''}" data-profile-tab="learning">How I learn</button><button class="${S.profileTab==='memory'?'active':''}" data-profile-tab="memory">Memory</button></div><form id="profile-form">${S.profileTab==='routine'?`<div class="profile-grid"><div><section class="form-section"><h2>The basics</h2><p>New accounts start with editable defaults. Nothing from the example workspace carries over.</p><div class="form-grid">${field('What should I call you?','name',p.name)}${field('Time zone','timezone',p.timezone)}</div></section><section class="form-section"><h2>When study is actually possible</h2><p>This is a window of possible time, not a promise to study every hour in it.</p><div class="form-grid">${field('Earliest start','start',p.study_window.start,'time')}${field('Latest finish','end',p.study_window.end,'time')}${field('Study minutes per day, at most','max_daily_minutes',p.max_daily_minutes,'number','min="15" max="720"')}${field('Preferred session length','session_minutes',p.session_minutes,'number','min="15" max="120" step="15"')}${field('Break between sessions','break_minutes',p.break_minutes,'number','min="0" max="60"')}</div></section></div><section class="form-section"><h2>Time that’s already spoken for</h2><p>Work, classes, sleep, commuting, family or a standing gym session. Ending after midnight is supported.</p>${p.commitments.map(c=>`<div class="commitment">${icon(c.kind==='sleep'?'moon':c.kind==='class'?'book':'clock')}<div class="commitment-content"><strong>${h(c.title)}</strong><p>${c.days.map(d=>WEEKDAYS[d]).join(', ')}<br>${h(c.start)}–${h(c.end)}${c.end<c.start?' · next day':''} · ${c.buffer_minutes} min buffer</p></div><button type="button" class="icon-button" data-remove-commitment="${h(c.id)}" aria-label="Remove ${h(c.title)}">${icon('close')}</button></div>`).join('')||'<p class="muted">No commitments yet. Add your real schedule before making a plan.</p>'}<button type="button" class="btn" data-act="add-commitment">${icon('plus')}Add a commitment</button></section></div>`:S.profileTab==='learning'?`<div class="profile-grid"><div><section class="form-section"><h2>Start with what you prefer</h2><p>Preferences guide the explanation. They are not permanent categories the agent puts you in.</p><label class="field">A helpful starting point<select name="format">${[['worked-examples','Show me a worked example'],['practice-first','Let me try it first'],['short-explanations','Keep it short and concrete'],['visual-explanations','Use a diagram when it helps'],['mixed','Mix it up based on the subject']].map(([v,l])=>`<option value="${v}" ${p.preferences.format===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Level of detail<select name="detail">${[['step-by-step','Step by step'],['concise','Concise'],['adaptive','Adapt as we go']].map(([v,l])=>`<option value="${v}" ${p.preferences.detail===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Anything else that helps?<textarea name="notes" rows="4" maxlength="2000" placeholder="For example: I understand code faster than formulas.">${h(p.preferences.notes)}</textarea></label></section><section class="form-section"><h2>Each class is different</h2>${S.data.snapshot.courses.map(c=>{const setting=p.course_settings.find(x=>x.id===String(c.id));return `<div class="form-grid"><label class="field">${h(c.name)}<input name="type-${c.id}" value="${h(setting?.type||'')}" placeholder="Math-heavy, coding, reading…"></label><label class="field">Starting task estimate (minutes)<input name="minutes-${c.id}" type="number" min="15" max="600" value="${setting?.baseline_minutes||60}"></label></div>`;}).join('')}</section></div><section class="form-section"><h2>Learning your pace</h2><p>After a session, tell me how long it took and how well you understood it. Estimates adapt separately for each class.</p>${S.data.snapshot.courses.map(c=>{const pace=coursePace(p,c.id);return `<div class="commitment"><div class="commitment-content"><strong>${h(c.name)}</strong><p>${pace.samples} check-ins · ${h(pace.confidence)}${pace.samples>=3?`<br>Planning multiplier: ${pace.factor.toFixed(2)}× your starting estimate`:''}</p></div></div>`;}).join('')}<button type="button" class="btn" data-act="checkin">Log a study session</button><div class="callout">A task completed by the agent does not count as evidence that you learned it.</div></section></div>`:`<section class="form-section"><h2>You decide what sticks.</h2><p>These facts were added or approved by you. ChatGPT sign-in does not import your ChatGPT conversations.</p>${S.data.proposals.map(m=>`<div class="callout">Suggested memory: ${h(m.text)}<div class="form-actions"><button type="button" class="btn small" data-memory="${h(m.id)}" data-accept="yes">Remember this</button><button type="button" class="text-button" data-memory="${h(m.id)}" data-accept="no">Dismiss</button></div></div>`).join('')}${p.memories.map(m=>`<div class="memory-entry"><p>${h(m.text)}<small>Confirmed by you${m.at?' · '+dLabel(m.at):''}</small></p><button type="button" class="icon-button" data-remove-memory="${h(m.id)}" aria-label="Forget this memory">${icon('close')}</button></div>`).join('')||'<p class="muted">No saved memories yet.</p>'}<label class="field">Add something the agent should remember<textarea name="new_memory" rows="3" maxlength="1000" placeholder="For example: On work nights, leave time to commute home."></textarea></label>${p.observations.length?`<button type="button" class="btn small" data-act="clear-observations">Forget learning history (${p.observations.length} check-ins)</button>`:''}</section>`}<div class="form-actions"><button class="btn primary" type="submit">Save changes</button><span class="muted">${S.demo?'Changes affect this preview only.':'Saved to your account and shared with your paired agent.'}</span></div></form></section>`;}
function connectionsView(){const signed=!S.demo,ai=S.data.ai,c=S.data.connection;return `<section class="view">${header('Your connections','Two ways to use Canvasly. One agent context, wherever you choose to work.')}<div class="connection-row"><div class="service-logo">${icon('agent')}</div><div class="connection-content"><h2>ChatGPT</h2><p>${ai?`Connected as ${h(ai.email)}. ${ai.plan_enabled?'Plan-usage permission granted.':'Identity connected; plan usage has not been authorized.'}`:'Sign in with ChatGPT to use your available plan allowance. No OpenAI API key and no silent switch to paid API billing.'}</p>${!S.config.local&&!S.config.chatgpt_ready?'<div class="callout warning">Hosted sign-in is not enabled yet. Canvasly needs an OpenAI-approved client ID. The button below will not pretend an account was connected.</div>':''}${!S.config.local&&!S.config.hosted_plan_ready?'<p class="muted">Website sign-in and hosted plan-funded inference are separate approvals.</p>':''}<div class="form-actions"><button class="btn primary" data-act="signin">Continue with ChatGPT</button>${ai?'<button class="btn" data-act="models">Load my models</button>':''}${signed?'<button class="text-button" data-act="signout">Sign out</button>':''}</div>${S.accounts.length?`<label class="field">Or reconnect a saved account<select id="saved-account"><option value="">Choose an account…</option>${S.accounts.map(a=>`<option value="${h(a.key)}">${h(a.label)} · ${h(a.registration)}</option>`).join('')}</select></label><button class="btn small" data-act="reconnect">Reconnect selected account</button>`:''}${S.models.length?`<form id="model-form" class="form-actions"><label class="field">Model available to your account<select name="model">${S.models.map(m=>`<option value="${h(m.slug)}" ${ai?.model===m.slug?'selected':''}>${h(m.name)}</option>`).join('')}</select></label><button class="btn" type="submit">Use this model</button></form>`:''}</div></div><div class="connection-row"><div class="service-logo canvas">${icon('book')}</div><div class="connection-content"><h2>Canvas</h2><p>${c?`Connected to ${h(c.origin)} as ${h(c.name)}.`:'Connect your school account. You sign in on your school’s own Canvas page; Canvasly never asks for your school password.'}</p>${signed?`<form id="canvas-form"><label class="field">Your school’s Canvas address<input name="origin" type="url" required placeholder="https://school.instructure.com" value="${h(c?.origin||'')}"><small>${S.config.canvas_hosts?.length?'Available schools: '+S.config.canvas_hosts.map(h).join(', '):'School authorization is required. No institution is configured yet.'}</small></label><div class="form-actions"><button class="btn" type="submit">Connect Canvas ${icon('arrow')}</button>${c?'<button class="text-button" type="button" data-act="sync">Sync courses</button><button class="text-button" type="button" data-act="disconnect">Disconnect</button>':''}</div></form>`:'<p class="muted">Sign in first, then connect your school.</p>'}${signed&&S.config.personal_test_enabled?`<details><summary>Personal local integration test</summary><form id="canvas-test-form">${field('Canvas address','origin',c?.origin||'','url')}${field('Your own temporary test token','token','','password','autocomplete="off"')}<button class="btn small" type="submit">Test my own account</button><p class="muted">Not an onboarding method for other students.</p></form></details>`:''}</div></div><div class="connection-row"><div class="service-logo">${icon('code')}</div><div class="connection-content"><h2>Use Canvasly through MCP</h2><p>Keep using your compatible AI client. It can read your profile and coursework, build your plan, and save complete deliverables to the same workspace. The client supplies the model.</p>${S.config.local?`<div class="form-actions"><button class="btn" data-act="${signed?'pair':'local'}">${signed?'Pair this workspace':'Start a local MCP workspace'}</button><button class="text-button" data-act="mcp-config">Connection instructions ${icon('arrow')}</button></div>`:'<div class="callout">The included MCP bridge runs locally over stdio. Hosted ChatGPT plugin/OAuth publication is not implemented in this build.</div>'}<p class="muted">${S.config.local?'Keep the local server running. The bridge never receives your ChatGPT or Canvas credentials.':''}</p></div></div><div class="connections-guide">${h(S.config.message||'Preview works without accounts.')}<br>Canvasly is independent of OpenAI, Instructure and your university.</div>${signed?'<div class="form-actions"><button class="btn small" data-act="export">Export my workspace</button><button class="text-button" data-act="erase">Erase my Canvasly data</button></div>':''}</section>`;}
function render(){const focused=document.activeElement?.id,selection=focused==='prompt'?[document.activeElement.selectionStart,document.activeElement.selectionEnd]:null;const title={agent:'Agent',work:'My work',schedule:'My week',profile:'About you',connections:'Connections'}[S.view]||'Agent';const name=S.data.profile.name||S.data.identity?.name||'Your workspace';root.innerHTML=`<div class="shell"><aside class="sidebar"><button class="brand" data-nav="agent"><img src="/favicon.svg" alt="">canvasly</button><nav class="nav" aria-label="Main navigation">${[['agent','agent','Agent'],['work','work','My work'],['schedule','calendar','My week'],['profile','profile','About you']].map(([v,i,l])=>`<button data-nav="${v}" class="${S.view===v?'active':''}">${icon(i)}${l}${v==='work'&&S.data.drafts.length?`<span class="count">${S.data.drafts.length}</span>`:''}</button>`).join('')}</nav><div class="nav-label">Your space</div><div class="recent"><button data-nav="work">Coursework, handled</button><button data-nav="schedule">Making room this week</button><button data-nav="profile">How I like to learn</button></div><div class="side-bottom"><nav class="nav"><button class="${S.view==='connections'?'active':''}" data-nav="connections">${icon('connect')}Connections</button></nav><p class="side-note">Less to carry.<br>More room for your life.</p><button class="account" data-nav="connections"><span class="avatar">${h(name.slice(0,1).toUpperCase())}</span><span><strong>${h(S.demo?'Alex · example':name)}</strong><small>${S.demo?'Preview workspace':S.data.ai?'ChatGPT connected':'MCP workspace'}</small></span><span class="spacer"></span>${icon('down')}</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-act="menu" aria-label="Open navigation">${icon('menu')}</button>${h(title)}<small>/ &nbsp; Your workspace</small></div><div class="top-actions">${S.demo?'<span class="preview-tag">Preview</span>':`<span class="preview-tag">${S.config.local?'Local':'Private beta'}</span>`}<button class="text-button" data-act="${S.view==='agent'?'new-chat':'export'}">${S.view==='agent'?'New conversation':'Export'}</button><button class="btn small" data-nav="connections">${S.demo?'Connect accounts':icon('connect')+' Connections'}</button></div></header><main id="main">${({agent:agentView,work:workView,schedule:scheduleView,profile:profileView,connections:connectionsView}[S.view]||agentView)()}</main></div></div>`;if(focused==='prompt'){const el=document.getElementById('prompt');el?.focus();el?.setSelectionRange(...selection);}}
function captureProfile(){const form=document.querySelector('#profile-form');if(!form||!S.editProfile)return;const f=new FormData(form),p=S.editProfile;if(S.profileTab==='routine'){p.name=f.get('name');p.timezone=f.get('timezone');p.study_window={start:f.get('start'),end:f.get('end')};for(const k of ['max_daily_minutes','session_minutes','break_minutes'])p[k]=Number(f.get(k));}else if(S.profileTab==='learning'){p.preferences={format:f.get('format'),detail:f.get('detail'),notes:f.get('notes')};p.course_settings=S.data.snapshot.courses.map(c=>({id:String(c.id),type:f.get('type-'+c.id),baseline_minutes:Number(f.get('minutes-'+c.id))}));}else if(f.get('new_memory')?.trim()){p.memories.push({id:crypto.randomUUID(),text:f.get('new_memory').trim(),source:'you',at:new Date().toISOString()});}}
async function saveProfile(){captureProfile();const profile=validateProfile({...S.editProfile,confirmed:true});if(S.demo){S.data.profile=profile;S.data.plan=null;S.data.profile_revision++;}else{await api('profile/save',{profile,profile_revision:S.data.profile_revision});await reload({renderPage:false});}S.editProfile=structuredClone(S.data.profile);render();toast(S.demo?'Saved in this preview.':'Your agent’s context is up to date.');}
function addCommitment(){captureProfile();show(modalHead('Protect time in your week','Choose the days this commitment starts. An end time before the start continues into the next day.')+`<form id="commitment-form"><div class="dialog-body">${field('What is it?','title','','text','required maxlength="100" placeholder="Work, classes, family…"')}<label class="field">Type<select name="kind">${['work','class','sleep','commute','activity','personal'].map(t=>`<option value="${t}">${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></label><div class="days-picker">${WEEKDAYS.map((d,i)=>`<label><input type="checkbox" name="days" value="${i}"><span>${d}</span></label>`).join('')}</div><div class="form-grid">${field('Starts','start','17:00','time','required')}${field('Ends','end','01:00','time','required')}${field('Buffer on each side (minutes)','buffer_minutes',15,'number','min="0" max="180"')}</div><p class="muted">These example times are editable. They are not assumptions about your schedule.</p></div><div class="dialog-footer"><small>Save your profile afterward to apply it.</small><button class="btn primary" type="submit">Add commitment</button></div></form>`);}
function checkin(){show(modalHead('How did that session go?','Your own study time helps improve future estimates. Agent-generated work doesn’t count as a study session.')+`<form id="checkin-form"><div class="dialog-body"><label class="field">Class<select name="course_id">${S.data.snapshot.courses.map(c=>`<option value="${c.id}">${h(c.name)}</option>`).join('')}</select></label>${field('What did you work on?','topic','','text','required maxlength="180"')}<div class="form-grid">${field('Expected minutes','estimated_minutes',45,'number','min="1" max="1200" required')}${field('Actual minutes','actual_minutes',60,'number','min="1" max="1200" required')}</div><label class="field">How well do you understand it now?<select name="understanding"><option value="1">1 — Still lost</option><option value="2">2 — Some parts clicked</option><option value="3" selected>3 — Mostly understand it</option><option value="4">4 — Can solve it myself</option><option value="5">5 — Could explain it to someone else</option></select></label></div><div class="dialog-footer"><small>Self-reported, not a verified mastery score.</small><button class="btn primary" type="submit">Save check-in</button></div></form>`);}
function delegateDialog(id,cid){const a=S.data.snapshot.assignments.find(a=>a.id===Number(id)&&a.course_id===Number(cid));if(!a)return;show(modalHead('Hand this one off',a.name)+`<form id="delegate-form" data-id="${a.id}" data-course="${a.course_id}"><div class="dialog-body"><p class="muted">${S.demo?'This creates a labeled example draft. No model request or real submission is made.':'The agent will read the instructions and available materials, produce the complete supported deliverable, then review it against the requirements.'}</p><label class="field">Anything the agent should know?<textarea name="notes" rows="4" maxlength="10000" placeholder="The required approach, what’s missing, or what you want to focus on…"></textarea></label><label class="check-label"><input type="checkbox" name="consent" required><span>${S.demo?'I understand this is a preview example.':'I’m authorized to share these materials with OpenAI for this task and want to use my ChatGPT plan allowance.'}</span></label><div class="callout">You’ll review the result. The agent cannot take proctored quizzes, execute code, or use external homework sites in this build.</div></div><div class="dialog-footer"><small>Nothing is submitted automatically.</small><button type="submit" class="btn primary">${S.demo?'Try example delegation':'Delegate assignment'} ${icon('arrow')}</button></div></form>`);}
function draftDialog(id){const original=S.data.drafts.find(d=>d.id===id);if(!original)return;S.detail=structuredClone(original);S.file=0;S.dirty=false;drawDraft();}
function drawDraft(){const d=S.detail,files=d.deliverable?.type==='online_upload'?d.deliverable.files:[],content=files.length?files[S.file]?.content:(d.deliverable?.type==='online_url'?d.deliverable.url:d.deliverable?.body)||'';const editable=['written','ready'].includes(d.stage);show(modalHead(d.title,stageLabel(d))+`<div class="dialog-body"><div class="edit-layout"><div>${files.length?`<div class="file-tabs">${files.map((f,i)=>`<button class="${i===S.file?'active':''}" data-file="${i}">${h(f.name)}</button>`).join('')}</div>`:''}${d.deliverable?`<label class="sr-only" for="editor">Draft content</label><textarea id="editor" class="draft-editor ${files.length?'code':''}" ${editable?'':'readonly'}>${h(content)}</textarea><div class="form-actions"><button class="btn small" data-act="download-draft">${icon('download')}Download ${files.length?'file':'draft'}</button>${editable?'<button class="btn small" data-act="save-draft">Save edits</button>':''}</div>`:blank('Your agent’s work will appear here.','The task is saved in the queue. Check My work for progress or any connection errors.')}<details><summary>Assignment instructions</summary><div class="brief-text">${h(d.assignment_brief?.instructions||'Instructions are stored with the task.')}</div></details></div><aside class="review-panel"><h3>A second look</h3>${d.review?`<p>${h(d.review.summary)}</p>${d.review.criteria.map(c=>`<div class="review-item"><strong>${h(c.criterion)} · ${h(c.status)}</strong><p>${h(c.feedback)}</p></div>`).join('')}<p>${d.review.concerns.map(h).join('<br>')}</p>`:'<p>A review runs after the draft is written. Editing the draft invalidates its previous review.</p>'}<div class="review-item"><strong>Materials considered</strong><p>${(d.source_names||[]).map(h).join('<br>')||'Assignment instructions and rubric.'}</p></div>${(d.context_warnings||[]).length?`<div class="callout warning">${d.context_warnings.map(h).join('<br>')}</div>`:''}<p>Model review is not a grade. Generated code has not been executed.</p></aside></div></div><div class="dialog-footer"><small>${S.demo?'Example only. Nothing was generated or submitted.':'Review the full work before choosing to submit it.'}</small><div class="row-actions">${editable?'<button class="btn" data-act="review-draft">Run review again</button>':''}${d.stage==='ready'?'<button class="btn primary" data-act="submit-confirm">Review & submit</button>':''}</div></div>`,true);}
function download(name,content){const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function mcpInstructions(){show(modalHead('Your agent, your client','Start the local Canvasly server, connect your school, and pair this workspace first.')+`<div class="dialog-body"><p class="muted">In a client that supports local stdio MCP servers, use this configuration. Replace the example path with the actual path on your computer.</p><pre class="draft-editor code">${h(JSON.stringify({mcpServers:{canvasly:{command:'node',args:['C:/path/to/canvasly/scripts/mcp.mjs']}}},null,2))}</pre><p class="muted">Then ask: “Read my Canvasly context, gather the scheduling lab’s requirements, create the full deliverable, and stage it in My work.”</p><p class="muted">This does not publish a remote ChatGPT connector. The bridge and website share the local account you explicitly paired.</p></div>`);}
async function makePlan(){if(S.demo){S.data.plan=buildStudyPlan(S.data.profile,S.data.snapshot.assignments,{delegated:S.data.drafts});navigate('schedule');}else{await api('plan',{});await reload({renderPage:false});navigate('schedule');}}
const acts={
 close:()=>modal.close(),menu:()=>document.body.classList.toggle('mobile-nav'),plan:makePlan,'add-commitment':addCommitment,checkin,'mcp-config':mcpInstructions,
 signin:async()=>{const result=await api('auth/start',{});location.assign(result.url);},reconnect:async()=>{const account=document.querySelector('#saved-account')?.value;if(!account)throw new Error('Choose a saved account.');location.assign((await api('auth/start',{account})).url);},
 local:async()=>{await api('auth/local',{});S.demo=false;S.data=await api('state');render();toast('Local workspace created. The MCP bridge is paired.');},pair:async()=>{await api('mcp/pair',{});toast('MCP bridge paired to this workspace.');mcpInstructions();},
 models:async()=>{S.models=await api('models');render();},sync:async()=>{if(S.demo){toast('Example courses are already loaded. Connect Canvas for live data.');return;}toast('Syncing the courses you can access…');const result=await api('sync',{});await reload({renderPage:false});render();toast(result.warnings?.length?'Synced with some missing or partial data. See My work.':'Coursework is up to date.');},
 disconnect:async()=>{const result=await api('canvas/disconnect',{});await reload({renderPage:false});render();toast(result.note);},signout:async()=>{const result=await api('auth/logout',{});S.demo=true;S.data=previewState();S.models=[];render();toast(result.remote_revocation_confirmed?'Signed out.':'Signed out locally. Remote revocation wasn’t confirmed; disconnect Canvasly in ChatGPT Settings.');},
 'new-chat':async()=>{if(!S.demo)await api('chat/clear',{});S.data.messages=[];S.composer='';render();},export:()=>download('canvasly-workspace.json',JSON.stringify(S.data,null,2)),
 'clear-observations':()=>{captureProfile();S.editProfile.observations=[];render();toast('History removed from the edit. Save changes to apply it.');},
 'download-draft':()=>{const d=S.detail;if(!d.deliverable)return;download(d.deliverable.type==='online_upload'?d.deliverable.files[S.file].name:d.title+'.txt',d.deliverable.type==='online_upload'?d.deliverable.files[S.file].content:d.deliverable.type==='online_url'?d.deliverable.url:d.deliverable.body);},
 'save-draft':async()=>{S.dirty=false;if(S.demo){S.detail.stage='written';S.detail.review=null;S.detail.version++;S.data.drafts=S.data.drafts.map(d=>d.id===S.detail.id?structuredClone(S.detail):d);}else{await api('draft/save',{id:S.detail.id,version:S.detail.version,deliverable:S.detail.deliverable});await reload({renderPage:false});S.detail=structuredClone(S.data.drafts.find(d=>d.id===S.detail.id));}drawDraft();render();toast('Saved. The previous review no longer applies.');},
 'review-draft':async()=>{if(S.dirty)throw new Error('Save your edits before reviewing the draft.');if(S.demo){S.detail.stage='ready';S.detail.review=exampleDraft({id:S.detail.assignment_id}).review;S.data.drafts=S.data.drafts.map(d=>d.id===S.detail.id?structuredClone(S.detail):d);drawDraft();toast('Example review restored.');}else{await api('draft/review',{id:S.detail.id});modal.close();await reload({renderPage:false});S.tab='delegated';navigate('work');toast('Review queued for the saved content. Save edits first if you changed the draft.');}},
 'submit-confirm':()=>{if(S.dirty)throw new Error('Save and re-review your edits before submitting.');const d=S.detail;show(modalHead('Submit this exact saved draft?',d.title)+`<form id="submit-form"><div class="dialog-body"><div class="callout warning">${S.demo?'Preview only. Submitting is disabled.':'This will send the saved deliverable to Canvas. It does not submit unsaved edits in the editor. Check all files, requirements and course rules first.'}</div>${field('Type SUBMIT to confirm','confirmation','','text','required autocomplete="off"')}<p class="muted">Existing Canvas submissions cannot be overwritten here.</p></div><div class="dialog-footer"><small>This action affects your course.</small><button class="btn primary" type="submit" ${S.demo?'disabled':''}>Submit to Canvas</button></div></form>`);},
 erase:()=>show(modalHead('Erase your Canvasly data?','This clears your coursework cache, profile, conversations and drafts. It does not remove assignments already submitted to Canvas.')+`<form id="erase-form"><div class="dialog-body">${field('Type DELETE to confirm','confirmation','','text','required autocomplete="off"')}</div><div class="dialog-footer"><button class="btn danger" type="submit">Erase data</button></div></form>`)
};
async function guarded(fn){try{await fn();}catch(e){toast(e.message,true);}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.suggest){S.composer=b.dataset.suggest;render();document.querySelector('#prompt')?.focus();return;}if(b.dataset.act){e.preventDefault();guarded(()=>acts[b.dataset.act]?.());return;}if(b.dataset.workTab){S.tab=b.dataset.workTab;render();return;}if(b.dataset.profileTab){captureProfile();S.profileTab=b.dataset.profileTab;render();return;}if(b.dataset.delegate){delegateDialog(b.dataset.delegate,b.dataset.course);return;}if(b.dataset.draft){draftDialog(b.dataset.draft);return;}if(b.dataset.file){S.file=Number(b.dataset.file);drawDraft();return;}if(b.dataset.removeCommitment){captureProfile();S.editProfile.commitments=S.editProfile.commitments.filter(c=>c.id!==b.dataset.removeCommitment);render();return;}if(b.dataset.removeMemory){captureProfile();S.editProfile.memories=S.editProfile.memories.filter(m=>m.id!==b.dataset.removeMemory);render();return;}if(b.dataset.memory){guarded(async()=>{if(S.demo){const m=S.data.proposals.find(p=>p.id===b.dataset.memory);if(b.dataset.accept==='yes')S.data.profile.memories.push({...m,source:'you'});S.data.proposals=S.data.proposals.filter(p=>p.id!==b.dataset.memory);}else{await api('memory/approve',{id:b.dataset.memory,accept:b.dataset.accept==='yes'});await reload({renderPage:false});}S.editProfile=null;render();});return;}if(b.dataset.job){guarded(async()=>{await api('job/control',{id:b.dataset.job,action:b.dataset.control});await reload({renderPage:false});render();});}});
document.addEventListener('input',e=>{if(e.target.id==='prompt')S.composer=e.target.value;if(e.target.id==='editor'&&S.detail?.deliverable){S.dirty=true;for(const btn of modal.querySelectorAll('[data-act=submit-confirm],[data-act=review-draft]')){btn.disabled=true;btn.title='Save your edits first.';}const d=S.detail.deliverable;if(d.type==='online_upload')d.files[S.file].content=e.target.value;else if(d.type==='online_url')d.url=e.target.value;else d.body=e.target.value;}});
document.addEventListener('change',e=>{if(e.target.id==='delegate-toggle')S.allowDelegation=e.target.checked;});
document.addEventListener('keydown',e=>{if(e.target.id==='prompt'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();document.querySelector('#chat-form')?.requestSubmit();}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form);guarded(async()=>{
 if(form.id==='chat-form'){const message=S.composer.trim();if(!message)return;if(S.demo){S.data.messages.push({id:crypto.randomUUID(),role:'user',text:message},{id:crypto.randomUUID(),role:'assistant',text:'This is a preview of the conversation experience, not a live model response. In your real workspace, I can read the course brief, take on a delegated assignment, or make a plan around your confirmed commitments.\n\nTry “Delegate an assignment” in My work, or edit the sample schedule in About you.'});}else{if(!sessionStorage.getItem('canvasly-context-consent')){show(modalHead('Give your agent the right context','Your message, saved profile, selected course details and relevant materials will be sent to OpenAI using your ChatGPT plan.')+`<div class="dialog-body"><p class="muted">No Canvas credentials are sent to the model. Confirm only for materials you’re authorized to share.</p><label class="check-label"><input id="context-consent" type="checkbox">I understand and agree for this session.</label><button class="btn primary" id="consent-send" type="button">Continue with my message</button></div>`);document.querySelector('#consent-send').onclick=()=>{if(!document.querySelector('#context-consent').checked)return;sessionStorage.setItem('canvasly-context-consent','yes');modal.close();document.querySelector('#chat-form').requestSubmit();};return;}await api('chat',{text:message,consent:true,allow_delegation:S.allowDelegation});await reload({renderPage:false});}S.composer='';render();return;}
 if(form.id==='profile-form')return saveProfile();
 if(form.id==='commitment-form'){const c={id:crypto.randomUUID(),title:f.get('title'),kind:f.get('kind'),days:f.getAll('days').map(Number),start:f.get('start'),end:f.get('end'),buffer_minutes:Number(f.get('buffer_minutes')),source:'you'};S.editProfile=validateProfile({...S.editProfile,commitments:[...S.editProfile.commitments,c]});modal.close();render();return;}
 if(form.id==='checkin-form'){const o=Object.fromEntries(f);o.format=S.data.profile.preferences.format;for(const k of ['estimated_minutes','actual_minutes','understanding'])o[k]=Number(o[k]);if(S.demo){S.data.profile=validateProfile({...S.data.profile,observations:[...S.data.profile.observations,{...o,id:crypto.randomUUID(),at:new Date().toISOString()}]});}else{await api('observation/add',o);await reload({renderPage:false});}S.editProfile=null;modal.close();render();toast('Check-in saved. Learning estimates use your own study history.');return;}
 if(form.id==='delegate-form'){const cid=Number(form.dataset.course),aid=Number(form.dataset.id);if(S.demo){const a=S.data.snapshot.assignments.find(a=>a.id===aid&&a.course_id===cid),d=exampleDraft(a);if(!S.data.drafts.some(x=>x.id===d.id))S.data.drafts.push(d);S.data.messages.push({id:crypto.randomUUID(),role:'assistant',text:`Example: ${a.name} is ready to inspect. This shows where a finished deliverable would appear; no model was called.`,draft_id:d.id});}else await api('delegate',{course_id:cid,assignment_id:aid,notes:f.get('notes'),consent:f.has('consent')});modal.close();if(!S.demo)await reload({renderPage:false});S.tab='delegated';navigate('work');toast(S.demo?'Example deliverable added.':'Assignment queued. Your worker will pick it up.');return;}
 if(form.id==='canvas-form'){location.assign((await api('canvas/start',{origin:f.get('origin')})).url);return;}
 if(form.id==='canvas-test-form'){await api('canvas/test',{origin:f.get('origin'),token:f.get('token')});form.reset();await reload({renderPage:false});render();toast('Your local test account is connected.');return;}
 if(form.id==='model-form'){await api('model/select',{model:f.get('model')});await reload({renderPage:false});render();toast('Model selected.');return;}
 if(form.id==='submit-form'){await api('draft/submit',{id:S.detail.id,content_hash:S.detail.content_hash,confirmation:f.get('confirmation')});modal.close();await reload({renderPage:false});render();toast('Submission receipt saved. Check Canvas to confirm.');return;}
 if(form.id==='erase-form'){await api('data/erase',{confirmation:f.get('confirmation')});modal.close();S.demo=true;S.data=previewState();S.models=[];render();toast('Application data erased.');}
});});
async function boot(){try{S.config=await api('config');try{S.data=await api('state');S.demo=false;}catch(e){if(e.status!==401)toast(e.message,true);}if(S.config.local)S.accounts=await api('auth/accounts').catch(()=>[]);}catch{toast('The server is unavailable. Showing the interactive preview.',true);}const requested=location.hash.slice(1);if(['agent','work','schedule','profile','connections'].includes(requested))S.view=requested;const error=new URL(location.href).searchParams.get('connection_error');if(error){toast(error,true);history.replaceState(null,'',location.pathname+location.hash);}render();}
await boot();setInterval(()=>{if(!S.demo&&!modal.open)guarded(()=>reload());},3000);
